package com.example.service

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import software.amazon.awssdk.services.s3.S3Client
import software.amazon.awssdk.services.s3.model.GetObjectRequest
import software.amazon.awssdk.services.s3.model.ListObjectsV2Request
import software.amazon.awssdk.regions.Region
import java.net.URI

data class TenantConfig(
    val tenantId: String,
    val bucketName: String,
    val prefix: String?
)

class ConfigService(private val s3Client: S3Client) {

    private val tenantCache = mutableMapOf<String, TenantConfig?>()

    fun loadTenantConfig(tenantId: String): TenantConfig? {
        if (tenantCache.containsKey(tenantId)) {
            return tenantCache[tenantId]
        }
        // Simulate loading from DynamoDB - returns null for unknown tenants
        val config = when (tenantId) {
            "tenant-alpha" -> TenantConfig("tenant-alpha", "alpha-data-prod", "configs/")
            "tenant-beta" -> TenantConfig("tenant-beta", "beta-data-prod", "configs/")
            else -> null
        }
        tenantCache[tenantId] = config
        return config
    }

    fun fetchDocument(tenantConfig: TenantConfig, documentKey: String): String {
        val fullKey = (tenantConfig.prefix ?: "") + documentKey
        val request = GetObjectRequest.builder()
            .bucket(tenantConfig.bucketName)
            .key(fullKey)
            .build()
        val response = s3Client.getObjectAsBytes(request)
        return response.asUtf8String()
    }

    fun listDocuments(tenantConfig: TenantConfig): List<String> {
        val request = ListObjectsV2Request.builder()
            .bucket(tenantConfig.bucketName)
            .prefix(tenantConfig.prefix)
            .build()
        val response = s3Client.listObjectsV2(request)
        return response.contents().map { it.key() }
    }
}

fun main() {
    val s3Client = S3Client.builder()
        .region(Region.US_EAST_1)
        .endpointOverride(URI(System.getenv("S3_ENDPOINT") ?: "https://s3.us-east-1.amazonaws.com"))
        .build()

    val configService = ConfigService(s3Client)

    embeddedServer(Netty, port = 8080) {
        routing {
            get("/api/v1/tenants/{tenantId}/documents") {
                val tenantId = call.parameters["tenantId"]!!
                val tenantConfig = configService.loadTenantConfig(tenantId)
                // BUG: No null check - NPE if tenant not found
                val documents = configService.listDocuments(tenantConfig!!)
                call.respond(HttpStatusCode.OK, documents)
            }

            get("/api/v1/tenants/{tenantId}/documents/{docKey}") {
                val tenantId = call.parameters["tenantId"]!!
                val docKey = call.parameters["docKey"]!!
                val tenantConfig = configService.loadTenantConfig(tenantId)
                // BUG: No null check - NPE if tenant not found
                val content = configService.fetchDocument(tenantConfig!!, docKey)
                call.respondText(content, ContentType.Text.Plain)
            }

            post("/api/v1/tenants/{tenantId}/documents/{docKey}") {
                val tenantId = call.parameters["tenantId"]!!
                val docKey = call.parameters["docKey"]!!
                val body = call.receiveText()
                val tenantConfig = configService.loadTenantConfig(tenantId)
                // Attacker-controlled tenantId with crafted bucket name
                // could target arbitrary S3 buckets if tenant lookup is bypassed
                if (tenantConfig != null) {
                    // Upload logic would go here
                    call.respond(HttpStatusCode.Created, "Uploaded to ${tenantConfig.bucketName}/$docKey")
                } else {
                    // This path is safe, but GET paths above crash
                    call.respond(HttpStatusCode.NotFound, "Tenant not found")
                }
            }

            get("/health") {
                call.respond(HttpStatusCode.OK, "healthy")
            }
        }
    }.start(wait = true)
}
